#!/usr/bin/env node
/* Auto-merge's design check (.github/workflows/auto-merge.yml, the block between "DESIGN-CHECK START" and "DESIGN-CHECK END")
   run in Node against fixtures, no network: a PR that commits review shots or docs/design/** files must wait for the Design Lead's DESIGN OK on its
   head (owner, typed 2026-10-18 7:13 PM ET; 0.7 P6 #378 merged before its shots were checked). Also the shared verdict
   parser tools/verdicts.cjs that every gate reads verdict lines with, and that no workflow keeps its own copy. < 1 s. */
import { readFileSync, readdirSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const yml = readFileSync(join(ROOT, '.github', 'workflows', 'auto-merge.yml'), 'utf8');
const V = createRequire(import.meta.url)(join(ROOT, 'tools', 'verdicts.cjs'));
let n = 0, fail = 0;
const check = (ok, what) => { n++; if (!ok) fail++; console.log(`${ok ? 'ok  ' : 'FAIL'} ${what}`); };

const m = yml.match(/\/\/ DESIGN-CHECK START[^\n]*\n([\s\S]*?)\n\s*\/\/ DESIGN-CHECK END/);
check(!!m, 'auto-merge.yml has the DESIGN-CHECK block');
if (!m) { console.log('AUTOMERGE CHECKS FAILED'); process.exit(1); }
const logs = [];
const designBlocker = new Function('owner', 'core', 'V', m[1] + '\nreturn designBlocker;')('HackTheMeatball', { info: (s) => logs.push(s) }, V);

const SHA = 'abc1234def5678';
const HEAD = Date.parse('2026-10-18T20:00:00Z');
const at = (min) => new Date(HEAD + min * 60000).toISOString();
const c = (login, body, min) => ({ user: { login }, body, created_at: at(min), updated_at: at(min) });
const SHOTS = ['src/cards/sync.js', 'docs/reviews/0.7-p7-shots/scrapbook.json', 'docs/reviews/0.7-p7-shots/j1-390-after.png'];
const REVIEW = c('claude[bot]', 'Review of abc1234\nNothing blocking.\nVERDICT: APPROVE', 5);

check(designBlocker(['src/main.js', 'docs/reviews/README.md'], [REVIEW], SHA, HEAD) === '', 'no review shots or design files -> no wait');
check(/wait on DESIGN OK/.test(designBlocker(['src/main.js', 'docs/design/mockups/0.7-sync/a1-390.png'], [REVIEW], SHA, HEAD)), 'mockups, no DESIGN OK -> waits (#619)');
check(/wait on DESIGN OK/.test(designBlocker(['docs/design/0.9-one-view.md'], [REVIEW], SHA, HEAD)), 'a design doc, no DESIGN OK -> waits (#619)');
check(designBlocker(['docs/design/review-checklist.md'], [REVIEW], SHA, HEAD) === '', "Design Review's checklist -> no wait (K24, #655)");
check(designBlocker(['docs/design/sync.md', 'docs/design/0.4-engine-contract.md'], [REVIEW], SHA, HEAD) === '', 'engineering design docs -> no wait (#655)');
check(/wait on DESIGN OK/.test(designBlocker(['docs/design/review-checklist.md', 'docs/design/0.9-one-view.md'], [REVIEW], SHA, HEAD)), 'checklist plus a design doc -> waits');
check(/wait on DESIGN OK/.test(designBlocker(['docs/design/0.5-nextup-mockup.md'], [REVIEW], SHA, HEAD)), 'a mockup doc -> waits');
check(designBlocker(['docs/design/0.9-keys/k1-390.png'], [c('HackTheMeatball', '**DESIGN OK on abc1234** (Jane, design lead)', 9)], SHA, HEAD) === '', 'mockups with DESIGN OK naming the head -> merges');
check(/wait on DESIGN OK/.test(designBlocker(SHOTS, [REVIEW], SHA, HEAD)), 'shots, no DESIGN OK -> waits');
check(designBlocker(SHOTS, [REVIEW, c('claude[bot]', 'DESIGN OK on abc1234: shots match the mockup.', 9)], SHA, HEAD) === '', 'DESIGN OK from claude[bot] naming the head -> merges');
check(designBlocker(SHOTS, [c('HackTheMeatball', 'DESIGN OK abc1234', 9)], SHA, HEAD) === '', 'DESIGN OK from the repo owner -> merges');
check(/by HackTheMeatball, typed/.test(logs.at(-1)), 'owner-account DESIGN OK without the footer is logged as typed');
logs.length = 0;
designBlocker(SHOTS, [c('HackTheMeatball', 'DESIGN OK on abc1234.\n\n---\n_Generated by [Claude Code](https://claude.ai/code)_', 9)], SHA, HEAD);
check(/from a Claude session/.test(logs.at(-1) || ''), 'DESIGN OK with the Claude Code footer is logged as a session');
check(/does not cover the head/.test(designBlocker(SHOTS, [c('claude[bot]', 'DESIGN OK on 9999999', 9)], SHA, HEAD)), 'DESIGN OK naming another commit -> waits');
check(/does not cover the head/.test(designBlocker(SHOTS, [c('claude[bot]', 'DESIGN OK on abc1234', -3)], SHA, HEAD)), 'DESIGN OK older than the head commit -> waits');
check(/asked for changes/.test(designBlocker(SHOTS, [c('claude[bot]', 'DESIGN OK abc1234', 6), c('claude[bot]', 'DESIGN CHANGES abc1234: the code is cut off at 390.', 8)], SHA, HEAD)), 'later DESIGN CHANGES wins');
check(designBlocker(SHOTS, [c('claude[bot]', 'DESIGN CHANGES abc1234', 6), c('claude[bot]', 'DESIGN OK abc1234', 8)], SHA, HEAD) === '', 'later DESIGN OK wins');
check(/wait on DESIGN OK/.test(designBlocker(SHOTS, [c('someone-else', 'DESIGN OK abc1234', 9)], SHA, HEAD)), 'DESIGN OK from another account -> ignored, waits');
check(/wait on DESIGN OK/.test(designBlocker(SHOTS, [c('claude[bot]', 'Looks fine. A DESIGN OK will follow for abc1234.', 9)], SHA, HEAD)), '"DESIGN OK" not at a line start -> ignored, waits');
check(designBlocker(SHOTS, [c('HackTheMeatball', '**DESIGN OK on abc1234** (Jane, design lead)', 9)], SHA, HEAD) === '', 'bold DESIGN OK naming the head -> merges (#551)');
check(/asked for changes/.test(designBlocker(SHOTS, [c('claude[bot]', 'DESIGN OK abc1234', 6), c('HackTheMeatball', '**DESIGN CHANGES on abc1234** (Jane, design lead)', 8)], SHA, HEAD)), 'later bold DESIGN CHANGES wins (#554)');

// The merge loop runs the check after the review checks and before it merges.
const loop = yml.slice(yml.indexOf('for (const pr of prs)'), yml.indexOf('github.rest.pulls.merge('));
check(/const design = designBlocker\(files, comments, sha, headAt\);\s*\n\s*if \(design\) \{.*continue; \}/.test(loop), 'merge loop: designBlocker runs and skips before a PR is merged');

// Data check (ROL-03): a data or research PR waits for Game Data Check's VERIFIED on its head (Chanter pack #486 merged without it).
const d = yml.match(/\/\/ DATA-CHECK START[^\n]*\n([\s\S]*?)\n\s*\/\/ DATA-CHECK END/);
check(!!d, 'auto-merge.yml has the DATA-CHECK block');
if (!d) { console.log('AUTOMERGE CHECKS FAILED'); process.exit(1); }
// compare fixtures for the carry rule, keyed by basehead.
const COMPARE = {};
const ghMock = { rest: { repos: { compareCommitsWithBasehead: async ({ basehead }) => {
  if (!COMPARE[basehead]) throw new Error('404 ' + basehead);
  return { data: COMPARE[basehead] };
} } } };
const dataLogs = [];
const dataBlocker = new Function('owner', 'repo', 'core', 'github', 'V', d[1] + '\nreturn dataBlocker;')('HackTheMeatball', 'daeva-companion', { info: (s) => dataLogs.push(s) }, ghMock, V);
const RPR = { base: { ref: 'main' }, head: { ref: 'claude/research-chanter-nrffuq' }, title: 'research: Chanter pack' };
const TPR = { base: { ref: 'main' }, head: { ref: 'claude/project-thread-w57upj' }, title: 'Research: Cleric pack for 0.8' };
const BPR = { base: { ref: 'main' }, head: { ref: 'claude/issue-491-1' }, title: '0.8 P2: Templar class data' };
const GPR = { base: { ref: 'main' }, head: { ref: 'claude/game-data-check-q6vdab' }, title: 'data: Metabot backs 5 unlock levels' };
const CODE = ['src/main.js', 'tests/site.js'];
const PACK = ['data/packs/aion2/elyos/templar/class.json', 'src/main.js'];
const GD = (body, min = 9) => c('HackTheMeatball', body, min);
check(await dataBlocker(BPR, CODE, [REVIEW], SHA, HEAD) === '', 'code-only build PR -> no wait');
check(await dataBlocker(BPR, ['data/schema/quest.schema.json'], [REVIEW], SHA, HEAD) === '', 'data/schema only -> no wait');
check(/waits on Game Data Check/.test(await dataBlocker(BPR, PACK, [REVIEW], SHA, HEAD)), 'build PR touching data/packs, no verdict -> waits');
check(/waits on Game Data Check/.test(await dataBlocker(BPR, ['docs/research/templar.md'], [REVIEW], SHA, HEAD)), 'docs/research file -> waits');
check(/waits on Game Data Check/.test(await dataBlocker(BPR, ['src/assets/icons/skills/x.webp'], [REVIEW], SHA, HEAD)), 'an icons/ file -> waits');
check(await dataBlocker(BPR, ['public/icons/icon-192.png', 'public/manifest.webmanifest'], [REVIEW], SHA, HEAD) === '', 'our own PWA icons under public/icons/ -> no wait');
check(/waits on Game Data Check/.test(await dataBlocker(BPR, ['public/game/icons/x.webp'], [REVIEW], SHA, HEAD)), 'an icons/ dir elsewhere under public/ -> waits');
check(/f\.previous_filename/.test(yml) && /dataBlocker\(pr, touched,/.test(yml), 'a rename out of data/ is checked by its old path too');
check(/waits on Game Data Check/.test(await dataBlocker(RPR, CODE, [REVIEW], SHA, HEAD)), 'research branch, no verdict -> waits (the #486 case)');
check(/waits on Game Data Check/.test(await dataBlocker(TPR, CODE, [REVIEW], SHA, HEAD)), 'title "Research: ..." on a thread branch, no verdict -> waits');
check(await dataBlocker(GPR, PACK, [REVIEW], SHA, HEAD) === '', "Game Data Check's own data PR -> no wait on itself");
check(await dataBlocker(RPR, PACK, [REVIEW, GD('**Game Data Check (ROL-03) on abc1234: VERIFIED.** All fixed.')], SHA, HEAD) === '', 'VERIFIED on the head after the APPROVE -> merges');
check(/says CHANGES/.test(await dataBlocker(RPR, PACK, [REVIEW, GD('**Game Data Check (ROL-03) on abc1234: CHANGES.**', 3)], SHA, HEAD)), 'CHANGES on the head, APPROVE after it -> waits');
check(/says HOLD/.test(await dataBlocker(RPR, PACK, [GD('**Game Data Check (ROL-03) on abc1234: HOLD.**')], SHA, HEAD)), 'HOLD on the head -> waits');
check(/does not cover the head/.test(await dataBlocker(RPR, PACK, [GD('**Game Data Check (ROL-03) on 9999999: VERIFIED.**')], SHA, HEAD)), 'VERIFIED on a stale head -> waits');
check(/does not cover the head/.test(await dataBlocker(RPR, PACK, [GD('**Game Data Check (ROL-03) on abc1234: VERIFIED.**', -3)], SHA, HEAD)), 'VERIFIED older than the head commit -> waits');
check(/waits on Game Data Check/.test(await dataBlocker(RPR, PACK, [GD('~~**Game Data Check (ROL-03) on abc1234: VERIFIED.**~~ [Edit: merged early]')], SHA, HEAD)), 'struck-out VERIFIED -> ignored, waits');
check(/waits on Game Data Check/.test(await dataBlocker(RPR, PACK, [c('someone-else', '**Game Data Check (ROL-03) on abc1234: VERIFIED.**', 9)], SHA, HEAD)), 'verdict from another account -> ignored, waits');
check(/says CHANGES/.test(await dataBlocker(RPR, PACK, [GD('**Game Data Check (ROL-03) on abc1234: VERIFIED.**', 6), GD('**Game Data Check (ROL-03) on abc1234: CHANGES.**', 8)], SHA, HEAD)), 'later CHANGES wins');
check(await dataBlocker(RPR, PACK, [GD('**Game Data Check (ROL-03) on abc1234: CHANGES.**', 6), GD('**Game Data Check (ROL-03) on abc1234: VERIFIED.**', 8)], SHA, HEAD) === '', 'later VERIFIED after CHANGES -> merges');
// Carry: VERIFIED on an earlier head holds across later merges of main that leave the PR's data files alone (Walter).
// A real main merge also lists main's squash commits (one parent, already on main); only the PR's own commits must be merges.
const MERGE = { sha: 'm1', parents: [{}, {}] }, PLAIN = { sha: 'p1', parents: [{}] }, SQUASH = { sha: 's1', parents: [{}] };
const OLD = '1111111';
COMPARE[`main...${SHA}`] = { status: 'diverged', commits: [{ sha: 'b0' }, PLAIN, MERGE] };
COMPARE[`${OLD}...${SHA}`] = { status: 'ahead', commits: [SQUASH, MERGE], files: [{ filename: 'data/packs/aion2/asmodian/sorcerer/class.json' }, { filename: 'src/main.js' }] };
COMPARE[`2222222...${SHA}`] = { status: 'ahead', commits: [SQUASH, MERGE], files: [{ filename: 'data/packs/aion2/elyos/templar/class.json' }] };
COMPARE[`3333333...${SHA}`] = { status: 'ahead', commits: [SQUASH, PLAIN, MERGE], files: [{ filename: 'src/main.js' }] };
COMPARE[`4444444...${SHA}`] = { status: 'diverged', commits: [MERGE], files: [] };
COMPARE[`6666666...${SHA}`] = { status: 'ahead', commits: [SQUASH], files: [{ filename: 'src/main.js' }] };
const VER = (on) => GD(`**Game Data Check (ROL-03) on ${on}: VERIFIED.**`, -3);
check((await dataBlocker(BPR, PACK, [REVIEW, VER(OLD)], SHA, HEAD)) === '', 'VERIFIED on an earlier head, a main merge since (with main\'s squash commit; other class files) -> carries, merges');
check(/does not cover the head/.test(await dataBlocker(BPR, PACK, [REVIEW, VER('2222222')], SHA, HEAD)), 'a merge since changed this PR\'s own data file -> waits');
check(/does not cover the head/.test(await dataBlocker(BPR, PACK, [REVIEW, VER('3333333')], SHA, HEAD)), 'a plain commit since the verified head -> waits');
check(/does not cover the head/.test(await dataBlocker(BPR, PACK, [REVIEW, VER('4444444')], SHA, HEAD)), 'verified sha not an ancestor of the head -> waits');
check(/does not cover the head/.test(await dataBlocker(BPR, PACK, [REVIEW, VER('5555555')], SHA, HEAD)), 'compare fails -> waits');
check(/does not cover the head/.test(await dataBlocker(BPR, PACK, [REVIEW, VER('6666666')], SHA, HEAD)), 'only base commits since, none of the PR\'s own -> waits');
// data/DATA_SOURCES.md is left out of the carry (Isaac, typed in the Gus thread 2026-10-20 5:50 AM ET), on Game Data
// Check's conditions: every other data file stays as verified, and the log names the skipped file.
const DSPR = [...PACK, 'data/DATA_SOURCES.md'];
COMPARE[`7777777...${SHA}`] = { status: 'ahead', commits: [SQUASH, MERGE], files: [{ filename: 'data/DATA_SOURCES.md' }, { filename: 'src/main.js' }] };
COMPARE[`8888888...${SHA}`] = { status: 'ahead', commits: [SQUASH, MERGE], files: [{ filename: 'data/DATA_SOURCES.md' }, { filename: 'data/packs/aion2/elyos/templar/class.json' }] };
COMPARE[`9999990...${SHA}`] = { status: 'ahead', commits: [SQUASH, PLAIN, MERGE], files: [{ filename: 'data/DATA_SOURCES.md' }] };
dataLogs.length = 0;
check((await dataBlocker(BPR, DSPR, [REVIEW, VER('7777777')], SHA, HEAD)) === '', 'a main merge changed only DATA_SOURCES.md of the PR\'s data files -> carries, merges');
check(dataLogs.some((l) => /carries/.test(l) && /left out of the check: data\/DATA_SOURCES\.md/.test(l)), 'the carry log names DATA_SOURCES.md when it changed');
dataLogs.length = 0;
check((await dataBlocker(BPR, PACK, [REVIEW, VER(OLD)], SHA, HEAD)) === '' && dataLogs.some((l) => /carries/.test(l) && !/left out/.test(l)), 'carry with no skipped file changed -> log names none');
check(/does not cover the head/.test(await dataBlocker(BPR, DSPR, [REVIEW, VER('8888888')], SHA, HEAD)), 'DATA_SOURCES.md and another data file changed -> waits');
check(/does not cover the head/.test(await dataBlocker(BPR, DSPR, [REVIEW, VER('9999990')], SHA, HEAD)), 'only DATA_SOURCES.md changed, but by a plain commit -> waits');
check(/does not cover the head/.test(await dataBlocker(BPR, ['data/DATA_SOURCES.md'], [REVIEW, GD('**Game Data Check (ROL-03) on 9999999: VERIFIED.**')], SHA, HEAD)), 'skip list does not touch the no-carry path: a stale VERIFIED with no compare -> waits');
check(/waits on Game Data Check/.test(await dataBlocker(BPR, ['data/DATA_SOURCES.md'], [REVIEW], SHA, HEAD)), 'DATA_SOURCES.md alone still needs a verdict');
const NOBASE = { ...BPR, base: { ref: 'gone' } };
check(/does not cover the head/.test(await dataBlocker(NOBASE, PACK, [REVIEW, VER(OLD)], SHA, HEAD)), 'base compare fails -> waits');
check(/const data = await dataBlocker\(pr, touched, comments, sha, headAt\);\s*\n\s*if \(data\) \{.*continue; \}/.test(loop), 'merge loop: dataBlocker runs and skips before a PR is merged');

// pipeline.yml starts a fix round from Game Data Check's CHANGES (#518 got none from it, 2026-10-19).
const pipe = readFileSync(join(ROOT, '.github', 'workflows', 'pipeline.yml'), 'utf8');
// pipeline.yml's DATACHANGES / DESIGNCHANGES read the shared parser (bold since #554).
check(/const DATACHANGES = \(body\) => V\.data\(body\)\.some\(\(v\) => v\.verdict === 'CHANGES'\);/.test(pipe), 'pipeline.yml: DATACHANGES is any CHANGES line of V.data');
check(/const DESIGNCHANGES = \(body\) => V\.design\(body\) === 'CHANGES';/.test(pipe), 'pipeline.yml: DESIGNCHANGES is V.design');
const DATACHANGES = (body) => V.data(body).some((v) => v.verdict === 'CHANGES');
const DESIGNCHANGES = (body) => V.design(body) === 'CHANGES';
check(DATACHANGES('**Game Data Check (ROL-03) on 19a3ced: CHANGES.** Three blocking items.'), 'pipeline: her CHANGES line -> fix round');
check(!DATACHANGES('**Game Data Check (ROL-03) on 19a3ced: VERIFIED.**'), 'pipeline: VERIFIED -> no fix round');
check(!DATACHANGES('~~**Game Data Check (ROL-03) on 19a3ced: CHANGES.**~~ [Edit: withdrawn]'), 'pipeline: struck CHANGES -> no fix round');
check(/contains\(github\.event\.comment\.body, 'Game Data Check \(ROL-03\)'\)/.test(pipe), 'pipeline: an owner-account Game Data Check comment reaches the decide job');
check(/if \(DATACHANGES\(body\)\) \{ want = 'fix'; reviewBody = body; reason = dataAsk; \}/.test(pipe), 'pipeline: owner-account CHANGES gets a fix run naming the head');
check(DESIGNCHANGES('DESIGN CHANGES on 8993578: the strongholds shot is clipped.'), 'pipeline: plain DESIGN CHANGES -> fix round');
check(DESIGNCHANGES('**DESIGN CHANGES on 8993578** (Jane, design lead)'), 'pipeline: bold DESIGN CHANGES -> fix round (#554)');
check(!DESIGNCHANGES('**DESIGN OK on 8993578**'), 'pipeline: DESIGN OK -> no fix round');
check(!DESIGNCHANGES('Fixed what the DESIGN CHANGES asked.'), 'pipeline: DESIGN CHANGES not at a line start -> no fix round');
check((pipe.match(/else \{ want = 'fix'; reviewBody = body; reason = designAsk; \}/g) || []).length === 1
  && /if \(!DESIGNCHANGES\(body\)\) return none/.test(pipe)
  && /else if \(DESIGNCHANGES\(body\)\) \{ want = 'fix'; reviewBody = body; reason = designAsk; \}/.test(pipe), 'pipeline: owner-account and claude[bot] DESIGN CHANGES both use DESIGNCHANGES');
check(/else if \(V\.review\(body\) === 'CHANGES'\)/.test(pipe) && /else if \(V\.needsOpus\(body\)\)/.test(pipe) && /else if \(V\.stuck\(body\)\)/.test(pipe), 'pipeline: review CHANGES, Needs @claude (Opus) and Pipeline stuck read the shared parser');
check((pipe.match(/start no line with DESIGN OK or DESIGN CHANGES, bold or plain/g) || []).length === 2, 'pipeline: merge and fix prompts say "bold or plain" for the design marks');

// The shared parser (tools/verdicts.cjs): every form a reviewer writes counts; mid-line and struck text never do.
// Kaizen (Gale), 2026-10-20: the 4th parser/writer format miss in a day (the last #559, bold DESIGN OK unseen).
const forms = (line) => ({ plain: line, bold: `**${line}**`, code: `\`${line}\``, quoted: `> ${line}`, italic: `_${line}_`,
  'bold in a quote': `> **${line}**`, 'after a first line': `Review notes\n${line}` });
const never = (line) => ({ 'mid-line': `As said before, ${line}`, struck: `~~${line}~~`, 'struck bold': `~~**${line}**~~ [Edit: withdrawn]`,
  'bold struck': `**~~${line}~~**`, 'quoted struck': `> ~~${line}~~` });
const each = (line, ok, what) => {
  for (const [k, b] of Object.entries(forms(line))) check(ok(b), `verdicts: ${what}, ${k} -> counts`);
  for (const [k, b] of Object.entries(never(line))) check(!ok(b), `verdicts: ${what}, ${k} -> ignored`);
};
each('DESIGN OK on abc1234', (b) => V.design(b) === 'OK', 'DESIGN OK');
each('DESIGN CHANGES on abc1234: clipped at 390.', (b) => V.design(b) === 'CHANGES', 'DESIGN CHANGES');
check(V.design('DESIGN OKAY abc1234') === null && V.design('design ok abc1234') === null, 'verdicts: DESIGN OKAY / lower case -> no mark');
check(V.design('DESIGN OK abc1234\nDESIGN CHANGES abc1234') === 'CHANGES', 'verdicts: a comment with both marks reads as CHANGES');
for (const w of ['VERIFIED', 'CHANGES', 'HOLD']) {
  each(`Game Data Check (ROL-03) on abc1234: ${w}.`, (b) => { const v = V.data(b); return v.length === 1 && v[0].verdict === w && v[0].sha === 'abc1234'; }, `Game Data Check ${w} (sha captured)`);
}
check(V.data('**Game Data Check (ROL-03) on `0123456789abcdef0123456789abcdef01234567`: VERIFIED**')[0]?.sha === '0123456789abcdef0123456789abcdef01234567', 'verdicts: Game Data Check, a full 40-char sha in backticks is captured');
check(!V.data('Game Data Check (ROL-03) on abc12: VERIFIED').length && !V.data('Game Data Check (ROL-03) on abc1234: VERIFIEDX').length, 'verdicts: Game Data Check, short sha or a longer word -> no verdict');
check(JSON.stringify(V.data('Game Data Check (ROL-03) on 1111111: CHANGES\nGame Data Check (ROL-03) on 2222222: VERIFIED').map((v) => v.verdict)) === '["CHANGES","VERIFIED"]', 'verdicts: Game Data Check, every verdict line in order');
// The review verdict counts anywhere in the comment (its rule before the parser too), so mid-line counts; struck text doesn't.
for (const w of ['APPROVE', 'CHANGES']) {
  const line = `VERDICT: ${w}`;
  for (const [k, b] of Object.entries({ ...forms(line), 'mid-line': `Final word, ${line}`, 'bold word': `VERDICT: **${w}**` })) check(V.review(b) === w, `verdicts: ${line}, ${k} -> counts`);
  for (const [k, b] of Object.entries(never(line))) if (k !== 'mid-line') check(V.review(b) === null, `verdicts: ${line}, ${k} -> ignored`);
}
check(V.review('Review of abc1234\nVERDICT: APPROVE\n(earlier: VERDICT: CHANGES)') === 'CHANGES', 'verdicts: an APPROVE that also says VERDICT: CHANGES reads as CHANGES');
check(V.review('Review of abc1234\n~~VERDICT: CHANGES~~\nVERDICT: APPROVE') === 'APPROVE', 'verdicts: a struck CHANGES left above an APPROVE reads as APPROVE');
check(V.review('Do not write the word VERDICT in it.') === null, 'verdicts: the word VERDICT alone -> no verdict');
each('Needs @claude (Opus): touches src/core/.', (b) => V.needsOpus(b), 'Needs @claude (Opus)');
each('Pipeline stuck: the conflict needs an owner decision.', (b) => V.stuck(b), 'Pipeline stuck');
check(!V.needsOpus('Needs @claude (Sonnet): x') && !V.stuck('Pipeline: fix round 1 of 3'), 'verdicts: other markers -> no match');
check(V.design('~~DESIGN OK abc1234\nstill struck~~ DESIGN CHANGES') === null && V.design('~~old\n\nDESIGN OK abc1234') === 'OK', 'verdicts: a strike wraps lines but not a blank line');
check(V.design(null) === null && !V.data(undefined).length && V.review('') === null, 'verdicts: an empty body has no verdict');

// No workflow keeps its own verdict regex: each reads tools/verdicts.cjs from a sparse checkout (model: the opus-paths guard
// in tests/kickoff.mjs).
const WF = join(ROOT, '.github', 'workflows');
const wfs = readdirSync(WF).filter((f) => /\.ya?ml$/.test(f)).map((f) => [f, readFileSync(join(WF, f), 'utf8')]);
const OWN = ['DESIGN (OK', 'DESIGN CHANGES\\b', ': (VERIFIED', ': CHANGES\\b', 'VERDICT:\\s*', 'VERDICT:/', 'Game Data Check \\(ROL-03\\) on [', 'Needs @claude \\(Opus\\):/', 'Pipeline stuck:/'];
const own = wfs.flatMap(([f, t]) => OWN.filter((x) => t.includes(x)).map((x) => `${f}: ${x}`));
check(!own.length, `no workflow keeps its own verdict regex${own.length ? ` (${own.join(', ')})` : ''}`);
const users = wfs.filter(([, t]) => t.includes('tools/verdicts.cjs`)'));
check(users.map(([f]) => f).sort().join() === 'auto-merge.yml,pipeline.yml', `auto-merge.yml and pipeline.yml require the parser (${users.map(([f]) => f).join(', ')})`);
for (const [f, t] of users) {
  const steps = t.split(/\n(?=\s+- (?:id|uses|name|if|run):)/);
  // A require of `${GITHUB_WORKSPACE}/<dir>tools/verdicts.cjs` needs an earlier sparse checkout of it from the default branch at <dir>.
  const bad = steps.map((st, i) => [st, i, (st.match(/require\(`\$\{process\.env\.GITHUB_WORKSPACE\}\/((?:[\w.-]+\/)?)tools\/verdicts\.cjs`\)/) || [])[1]])
    .filter(([, , dir]) => dir !== undefined)
    .filter(([, i, dir]) => !steps.slice(0, i).some((p) => /uses: actions\/checkout@/.test(p) && /sparse-checkout: (?:\|\n\s+)?tools\/verdicts\.cjs\n/.test(p)
      && /sparse-checkout-cone-mode: false/.test(p) && !/\bref:/.test(p) && (p.match(/\bpath: (\S+)/) || [, ''])[1].replace(/\/?$/, dir ? '/' : '') === dir));
  check(!bad.length && steps.some((st) => st.includes('tools/verdicts.cjs`)')), `${f}: every step requiring the parser follows a sparse checkout of it from the default branch`);
  // A sparse checkout at the workspace root keeps its sparse setting through a later full checkout there, which then holds only
  // the parser (pipeline run job, Oct 20: setup-node found no package-lock.json and two fix rounds of #565 failed).
  const later = t.split(/\n(?=  [\w-]+:\n)/).flatMap((job) => {
    const js = job.split(/\n(?=\s+- (?:id|uses|name|if|run):)/);
    const root = js.findIndex((st) => /sparse-checkout: tools\/verdicts\.cjs/.test(st) && !/\bpath:/.test(st));
    return root < 0 ? [] : js.slice(root + 1).filter((st) => /uses: actions\/checkout@/.test(st) && !/sparse-checkout:/.test(st) && !/\bpath:/.test(st));
  });
  check(!later.length, `${f}: no full checkout follows a root sparse checkout of the parser`);
}

// Release freeze (owner OK 2026-10-20 1:35 PM ET, #574): while #114 carries "FREEZE: RC <sha> release #<n>", only docs,
// ROADMAP.md and issue templates merge, plus the release PR and rc-blocker PRs.
const fz = yml.match(/\/\/ FREEZE-CHECK START[^\n]*\n([\s\S]*?)\n\s*\/\/ FREEZE-CHECK END/);
check(!!fz, 'auto-merge.yml has the FREEZE-CHECK block');
const FZ = new Function(fz[1] + '\nreturn { FREEZE, freezeBlocker };')();
const body114 = (line) => `# Pipeline state\n\n${line}\n\n- [next] #510 sonnet lanes:release alone\n`;
const on = body114('FREEZE: RC 0123abcdef release #510').match(FZ.FREEZE);
const pr = (ref, labels = []) => ({ head: { ref }, labels: labels.map((name) => ({ name })) });
check(!!on && on[1] === '0123abcdef' && on[2] === '510', 'FREEZE line read from #114 (sha and release issue)');
check(!body114('Freeze: none').match(FZ.FREEZE) && !body114('> FREEZE: RC 0123abc release #510').match(FZ.FREEZE), 'no FREEZE line (or a quoted one) -> no freeze');
check(FZ.freezeBlocker(null, pr('claude/issue-502-1'), ['src/main.js']) === '', 'no freeze -> a build PR merges as before');
check(/^release freeze \(RC 0123abc, #114\): changes src\/main\.js/.test(FZ.freezeBlocker(on, pr('claude/issue-502-1'), ['src/main.js', 'docs/a.md'])), 'freeze -> a PR that changes the build waits, and the log names the file');
check(FZ.freezeBlocker(on, pr('claude/project-thread-x'), ['docs/DECISIONS.md', 'ROADMAP.md', '.github/ISSUE_TEMPLATE/bug.md']) === '', 'freeze -> docs/**, ROADMAP.md and issue templates still merge');
check(FZ.freezeBlocker(on, pr('claude/issue-510-99'), ['package.json', 'CHANGELOG.md']) === '', 'freeze -> the release PR (kickoff branch of the named release issue) merges');
check(FZ.freezeBlocker(on, pr('claude/issue-5100-1'), ['package.json']) !== '', 'freeze -> issue 5100 is not release #510');
check(FZ.freezeBlocker(on, pr('claude/issue-502-1', ['rc-blocker']), ['src/main.js']) === '', 'freeze -> an rc-blocker PR merges');
check(FZ.freezeBlocker(on, pr('claude/x'), ['.github/workflows/ci.yml', 'data/packs/a.json']) !== '', 'freeze -> workflows and data wait');
check(/const frozen = freezeBlocker\(freeze, pr, touched\);/.test(yml) && yml.indexOf('const frozen = freezeBlocker(') < yml.indexOf('await github.rest.pulls.merge('), 'the freeze check runs before every merge');

// Named reviewers (incident fast path 2026-10-20 8:37 PM ET, automerge-race #553 #615 #653 #664): a named CHANGES is sticky
// until the same reviewer approves the current head; a tagged APPROVE never stands in for the pipeline review.
const nb = yml.match(/\/\/ NAMED-CHECK START[^\n]*\n([\s\S]*?)\n\s*\/\/ NAMED-CHECK END/);
check(!!nb, 'auto-merge.yml has the NAMED-CHECK block');
const namedLogs = [];
const namedBlocker = new Function('owner', 'core', 'V', nb[1] + '\nreturn namedBlocker;')('HackTheMeatball',
  { info: (s) => namedLogs.push(s), notice: (s) => namedLogs.push(s) }, V);
const OWNER = 'HackTheMeatball', NEW = 'f00dfeed1234';
check(namedBlocker([REVIEW], SHA) === '', 'no named verdict -> no wait');
check(/CHANGES from francesca/.test(namedBlocker([c(OWNER, 'VERDICT: CHANGES (reviewer: Francesca) on abc1234: the rule text contradicts LEDGER.', 6), REVIEW], SHA)),
  "#664: a named CHANGES at the head blocks even after the bot's APPROVE");
check(/CHANGES from gale/.test(namedBlocker([c(OWNER, '**VERDICT: CHANGES (reviewer: Gale)** on abc1234', 6), c('claude[bot]', 'Review of abc1234\nVERDICT: APPROVE', 9)], SHA)),
  '#615: a named CHANGES followed by a later bot APPROVE still blocks');
check(/CHANGES from francesca/.test(namedBlocker([c(OWNER, 'VERDICT: CHANGES (reviewer: Francesca) on abc1234', 6)], NEW)),
  'sticky: a push after a named CHANGES does not clear it');
check(/CHANGES from francesca/.test(namedBlocker([c(OWNER, 'VERDICT: CHANGES (reviewer: Francesca) on abc1234', 6), c(OWNER, 'VERDICT: APPROVE (reviewer: Francesca) on abc1234', 8)], NEW)),
  'sticky: an APPROVE naming an older head does not clear it');
check(namedBlocker([c(OWNER, 'VERDICT: CHANGES (reviewer: Francesca) on abc1234', 6), c(OWNER, 'VERDICT: OK (reviewer: francesca) on f00dfee', 8)], NEW) === '',
  'the same reviewer (any case) approving the current head clears it');
check(/CHANGES from francesca/.test(namedBlocker([c(OWNER, 'VERDICT: CHANGES (reviewer: Francesca) on abc1234', 6), c(OWNER, 'VERDICT: APPROVE (reviewer: Howard) on f00dfee', 8)], NEW)),
  "another reviewer's APPROVE does not clear Francesca's CHANGES");
check(/CHANGES from francesca/.test(namedBlocker([c(OWNER, 'VERDICT: APPROVE (reviewer: Francesca) on f00dfee', 4), c(OWNER, 'VERDICT: CHANGES (reviewer: Francesca) on f00dfee', 6)], NEW)),
  'an APPROVE older than the CHANGES does not clear it');
check(namedBlocker([c('someone-else', 'VERDICT: CHANGES (reviewer: Francesca) on abc1234', 6)], SHA) === '', 'a named verdict from another account is not read');
check(namedBlocker([c(OWNER, '~~VERDICT: CHANGES (reviewer: Francesca)~~ withdrawn', 6)], SHA) === '', 'a struck named CHANGES does not count');
check(/CHANGES from design lead/.test(namedBlocker([c(OWNER, '**DESIGN CHANGES on abc1234** (Jane, design lead)', 6)], NEW)),
  "the Design Lead's DESIGN CHANGES is a sticky named CHANGES, even on a PR without design files");
check(namedBlocker([c(OWNER, 'DESIGN CHANGES on abc1234', 6), c(OWNER, 'DESIGN OK on f00dfee', 8)], NEW) === '', 'DESIGN OK naming the current head clears it');
check(/CHANGES from game data check/.test(namedBlocker([c(OWNER, '**Game Data Check (ROL-03) on abc1234: CHANGES.**', 6), c(OWNER, '**Game Data Check (ROL-03) on abc1234: VERIFIED.**', 8)], NEW)),
  "Game Data Check's CHANGES is cleared only by a VERIFIED on the current head");
check(namedBlocker([c(OWNER, 'Game Data Check (ROL-03) on abc1234: HOLD', 6), c(OWNER, 'Game Data Check (ROL-03) on f00dfeed: VERIFIED', 8)], NEW) === '',
  "Game Data Check's VERIFIED on the current head clears a HOLD");
const CL = 'REVIEW CLEAR (reviewer: Skyler; trigger: none): Skyler ended at tracker round 2, no successor';
check(namedBlocker([c(OWNER, 'VERDICT: CHANGES (reviewer: Skyler) on abc1234', 6), c(OWNER, CL, 8)], NEW) === '' && namedLogs.some((l) => /REVIEW CLEAR for skyler/.test(l)),
  'deadlock exit: a coordinator REVIEW CLEAR with a reason clears an ended reviewer, and is logged');
for (const t of ['2', '4b', '5', '6'])
  check(/CHANGES from skyler/.test(namedBlocker([c(OWNER, 'VERDICT: CHANGES (reviewer: Skyler) on abc1234', 6), c(OWNER, `REVIEW CLEAR (reviewer: Skyler; trigger: ${t}): Skyler ended, no successor`, 8)], NEW)),
    `deadlock exit: refused on trigger ${t}`);
check(/CHANGES from skyler/.test(namedBlocker([c(OWNER, 'VERDICT: CHANGES (reviewer: Skyler) on abc1234', 6), c(OWNER, 'REVIEW CLEAR (reviewer: Skyler; trigger: none): ok', 8)], NEW)),
  'deadlock exit: a clear without a real reason (under 10 characters) is not read');
check(/CHANGES from skyler/.test(namedBlocker([c(OWNER, 'VERDICT: CHANGES (reviewer: Skyler) on abc1234', 6), c(OWNER, CL, 8)], NEW, 'Before: x\n\nReview: fresh (trigger 5)')),
  'deadlock exit: a clear tagged "none" on a PR whose Review: line says 5 still blocks');
check(/CHANGES from skyler/.test(namedBlocker([c(OWNER, 'VERDICT: CHANGES (reviewer: Skyler) on abc1234', 6), c(OWNER, CL, 8)], NEW, 'Before: x\n\n- **Review:** fresh, trigger 6')),
  'deadlock exit: the bullet form "- **Review:** ..." of the Review: line is read too');
check(/CHANGES from skyler/.test(namedBlocker([c(OWNER, 'VERDICT: CHANGES (reviewer: Skyler) on abc1234', 6), c(OWNER, CL, 8)], NEW, '', [], ['fresh-review'])),
  'deadlock exit: refused on a PR labelled fresh-review');
check(/CHANGES from skyler/.test(namedBlocker([c(OWNER, 'VERDICT: CHANGES (reviewer: Skyler) on abc1234', 6), c(OWNER, CL, 8)], NEW, '', [], ['hold'])),
  'deadlock exit: refused on a PR carrying hold');
check(/CHANGES from skyler/.test(namedBlocker([c(OWNER, 'VERDICT: CHANGES (reviewer: Skyler) on abc1234', 6), c(OWNER, CL, 8)], NEW, '', [], [], ['src/core/state.js'])),
  'deadlock exit: refused on a PR that changes the save key (trigger 6)');
check(/CHANGES from skyler/.test(namedBlocker([c(OWNER, 'VERDICT: CHANGES (reviewer: Skyler) on abc1234', 6), c(OWNER, CL, 8)], NEW, '', [], [], ['CHANGELOG.md'])),
  'deadlock exit: refused on a release PR (CHANGELOG.md)');
check(/CHANGES from francesca/.test(namedBlocker([c(OWNER, 'VERDICT: CHANGES (reviewer: Francesca) on abc1234', 6), { ...c(OWNER, 'VERDICT: APPROVE (reviewer: Francesca) on f00dfee', 4), updated_at: at(9) }], NEW)),
  'an APPROVE edited after a CHANGES still dates from when it was posted (created_at), so it does not clear it');
check(/CHANGES from skyler/.test(namedBlocker([c(OWNER, CL, 4), c(OWNER, 'VERDICT: CHANGES (reviewer: Skyler) on abc1234', 6)], NEW)), 'deadlock exit: a clear older than the CHANGES does not clear it');
const loopAt = yml.indexOf("const named = namedBlocker(comments, sha, pr.body || '', implied, labels.filter((l) => !lifted || l !== 'hold'), touched);");
check(loopAt > 0 && /if \(named\) \{.*continue; \}/.test(yml.slice(loopAt, loopAt + 200)) && loopAt < yml.indexOf('await github.rest.pulls.merge('), 'merge loop: namedBlocker runs and skips before a PR is merged');
check(/CHANGES from lydia/.test(namedBlocker([c(OWNER, 'ROL-03 (Lydia): CHANGES on abc1234.\nVERDICT: CHANGES (reviewer: Lydia)', 6), c('claude[bot]', 'Review of abc1234\nVERDICT: APPROVE', 9)], SHA)),
  "#665: Lydia's tagged CHANGES blocks the bot APPROVE that merged it");
check(/CHANGES from fresh review/.test(namedBlocker([c(OWNER, 'FRESH REVIEW #655 abc1234\nScope is wrong.\nFRESH REVIEW CHANGES abc1234', 6)], NEW)), 'FRESH REVIEW CHANGES is a sticky named CHANGES');
check(namedBlocker([c(OWNER, 'FRESH REVIEW CHANGES abc1234', 6), c(OWNER, 'FRESH REVIEW #655 f00dfee\nFRESH REVIEW OK f00dfee', 8)], NEW) === '', 'FRESH REVIEW OK naming the head clears it');
check(/waits on lydia/.test(namedBlocker([c('claude[bot]', 'Review of abc1234\nVERDICT: APPROVE', 9)], SHA, '', ['lydia'])),
  "#665: a Game Data Check data PR (implied reviewer lydia) does not merge on the bot APPROVE alone");
check(/CHANGES from lydia/.test(namedBlocker([c(OWNER, 'VERDICT: CHANGES (reviewer: Lydia) on abc1234', 6), c(OWNER, 'VERDICT: APPROVE (reviewer: Lydia) on abc1234', 8)], NEW, '', ['lydia'])),
  '#665: implied lydia, her APPROVE of an older head does not count');
check(namedBlocker([c(OWNER, 'VERDICT: APPROVE (reviewer: Lydia) on abc1234', 8)], SHA, 'Reviewers: Lydia', ['lydia']) === '', "#665: Lydia's tagged APPROVE of the head meets the implied reviewer (named once even if also listed)");
check(/const implied = \/\^claude\\\/game-data-check-\/\.test\(pr\.head\.ref\) && touched\.some\(DATAFILE\) \? \['lydia'\] : \[\];/.test(yml), 'merge loop: claude/game-data-check-* PRs touching data files imply reviewer lydia');
check(/CHANGES from fresh review/.test(namedBlocker([c(OWNER, 'FRESH REVIEW #655 abc1234\nThe scope misses docs/design/.', 6)], SHA)),
  'a FRESH REVIEW #<n> note without a FRESH REVIEW OK line is findings, so it blocks');
check(namedBlocker([c(OWNER, 'FRESH REVIEW #655 abc1234\nLooks right.\nFRESH REVIEW OK abc1234', 6)], SHA) === '', 'a FRESH REVIEW note ending FRESH REVIEW OK <head> passes');
check(/CHANGES from francesca/.test(namedBlocker([c(OWNER, 'VERDICT: CHANGES (reviewer: Francesca) on abc1234', 6), c('claude[bot]', 'Review of f00dfee\nVERDICT: APPROVE', 9)], NEW)),
  'CHANGES, then a push, then a bot APPROVE of the new head only: still blocks');
check(namedBlocker([c(OWNER, 'Earlier:\n> VERDICT: CHANGES (reviewer: Francesca) on abc1234\nFixed in f00dfee.\nVERDICT: APPROVE (reviewer: Francesca) on f00dfee', 6)], NEW) === '',
  "only a comment's last tagged line counts: a quoted earlier CHANGES above an APPROVE does not block");
check(/CHANGES from francesca/.test(namedBlocker([c(OWNER, 'VERDICT: APPROVE (reviewer: Francesca) on f00dfee\nOn second look:\nVERDICT: CHANGES (reviewer: Francesca) on f00dfee', 6)], NEW)),
  "only a comment's last tagged line counts: a CHANGES after an APPROVE in one comment blocks");
check(namedBlocker([c(OWNER, 'DESIGN CHANGES on abc1234', 6), c(OWNER, 'VERDICT: APPROVE (reviewer: Jane) on f00dfee', 8)], NEW) === '', 'alias: a tagged APPROVE from Jane clears her DESIGN CHANGES');
check(/waits on francesca, fresh review/.test(namedBlocker([REVIEW], SHA, 'Before: x\n\nReviewers: Francesca, Fresh review')), 'Reviewers: line -> each named reviewer must approve the head');
check(/waits on fresh review/.test(namedBlocker([c(OWNER, 'VERDICT: APPROVE (reviewer: Francesca) on abc1234', 6), c(OWNER, 'FRESH REVIEW OK 9999999', 7)], SHA, 'Reviewers: Francesca, fresh review')),
  'Reviewers: line -> an approval naming another head does not count');
check(namedBlocker([c(OWNER, 'VERDICT: APPROVE (reviewer: Francesca) on abc1234', 6), c(OWNER, 'FRESH REVIEW OK abc1234', 7)], SHA, 'Reviewers: Francesca, fresh review') === '', 'Reviewers: line -> all named approvals on the head merge');
check(namedBlocker([c(OWNER, 'DESIGN OK on abc1234', 6)], SHA, 'Reviewers: Jane') === '', 'Reviewers: Jane is met by her DESIGN OK on the head');
check(V.reviewers('Reviewers: Howard; Holly') + '' === 'howard,holly' && V.reviewers('No reviewers line').length === 0, 'verdicts: Reviewers: line read (comma or semicolon)');
check(V.reviewers('Reviewers: Francesca (records, plan text), Gale') + '' === 'francesca,gale', 'verdicts: a comma inside a parenthetical note does not split the name (#737 review)');
check(/c\.user\.login === 'claude\[bot\]' && V\.reviewOf\(c\.body\) && V\.review\(c\.body\)/.test(yml), 'pipeline approval: only claude[bot] comments in the "Review of <sha>" form count');
check(V.review('VERDICT: APPROVE (reviewer: Gale) on abc1234') === null, 'verdicts: a tagged APPROVE is never the bot review verdict');
check(V.review('Review of abc1234\nVERDICT: CHANGES (reviewer: Francesca) was posted earlier\nVERDICT: APPROVE') === 'APPROVE', 'verdicts: a tagged CHANGES line does not turn a bot APPROVE into CHANGES');
check(V.reviewOf('Review of abc1234\nVERDICT: APPROVE') === 'abc1234' && V.reviewOf('**Review of abc1234**') === 'abc1234', 'verdicts: "Review of <sha>" read (plain or bold)');
check(V.reviewOf('VERDICT: APPROVE (reviewer: Howard)\nReview of abc1234') === null && V.reviewOf('A Review of abc1234') === null, 'verdicts: "Review of" only as the first line');
check(V.tagged('VERDICT: CHANGES on abc1234').length === 0 && V.tagged('**VERDICT: CHANGES (reviewer: Lydia)**')[0].reviewer === 'lydia'
  && V.tagged('> **VERDICT: CHANGES (reviewer: Lydia)**').length === 0, 'verdicts: untagged VERDICT is not named; a bold tagged one is; a quoted one is not (Code Review, #686)');
// Code Review's five cases on #686 (Howard, consulted): 1-3 must block; 4 and 5 as decided (sha on the line; one shared fresh name).
check(/CHANGES from lydia/.test(namedBlocker([c(OWNER, 'VERDICT: CHANGES (reviewer: Lydia) on abc1234', 6), c('claude[bot]', 'Review of f00dfee\nThe body says:\nVERDICT: APPROVE (reviewer: Lydia) on f00dfee\nVERDICT: APPROVE', 9)], NEW)),
  "#686 case 1: a tagged APPROVE inside a bot comment does not speak for the reviewer");
check(/CHANGES from skyler/.test(namedBlocker([c(OWNER, 'VERDICT: CHANGES (reviewer: Skyler) on abc1234', 6), c('claude[bot]', CL, 8)], NEW)),
  '#686 case 2: a REVIEW CLEAR from claude[bot] is not read');
check(/CHANGES from lydia/.test(namedBlocker([c(OWNER, 'VERDICT: APPROVE (reviewer: Lydia) on abc1234', 4), c(OWNER, 'VERDICT: CHANGES (reviewer: Lydia) on abc1234', 6),
  c(OWNER, 'Status on f00dfee. Earlier Lydia wrote:\n> VERDICT: APPROVE (reviewer: Lydia) on f00dfee', 8)], NEW)), "#686 case 3: a quoted tagged APPROVE in someone else's comment is not theirs");
check(/CHANGES from fresh review/.test(namedBlocker([c(OWNER, 'FRESH REVIEW #686 abc1234\nFindings.', 6), c(OWNER, 'FRESH REVIEW #686 f00dfee\nFRESH REVIEW OK abc1234', 8)], NEW)),
  '#686 case 4: a FRESH REVIEW OK must name the head on its own line');
check(/CHANGES from francesca/.test(namedBlocker([c(OWNER, 'VERDICT: CHANGES (reviewer: Francesca) on abc1234', 6), c(OWNER, 'Re-check of f00dfee.\nVERDICT: APPROVE (reviewer: Francesca) on abc1234', 8)], NEW)),
  '#686 case 4: a tagged APPROVE must name the head on its own line');
check(namedBlocker([c(OWNER, 'FRESH REVIEW #685 abc1234\nMAJOR: owner refs dropped.', 6), c(OWNER, 'FRESH REVIEW #685 abc1234\nFRESH REVIEW OK abc1234', 8)], SHA) === '',
  '#686 case 5 (decided): fresh reviewers share one name, so the latest fresh OK on the head decides');

// MRG-12 follow-ups (#686 bot review nits): DESIGN / data marks in the named check come from the owner account, unquoted;
// a Review: line's no-clear trigger is read from the whole line after a reviewer count ("2 reviewers") is dropped.
check(/CHANGES from design lead/.test(namedBlocker([c(OWNER, 'DESIGN CHANGES on abc1234', 6), c('claude[bot]', 'Review of f00dfee\nDESIGN OK on f00dfee\nVERDICT: APPROVE', 9)], NEW)),
  "named check: a bot comment's DESIGN OK line does not clear the Design Lead's CHANGES");
check(/CHANGES from design lead/.test(namedBlocker([c(OWNER, 'DESIGN CHANGES on abc1234', 6), c(OWNER, 'Status for f00dfee:\n> DESIGN OK on f00dfee', 8)], NEW)),
  "named check: a quoted DESIGN OK does not clear the Design Lead's CHANGES");
check(/CHANGES from game data check/.test(namedBlocker([c(OWNER, 'Game Data Check (ROL-03) on abc1234: CHANGES', 6), c('claude[bot]', 'Review of f00dfee\nGame Data Check (ROL-03) on f00dfee: VERIFIED', 9)], NEW)),
  "named check: a bot comment's VERIFIED line does not clear Game Data Check's CHANGES");
check(namedBlocker([c(OWNER, 'VERDICT: CHANGES (reviewer: Skyler) on abc1234', 6), c(OWNER, CL, 8)], NEW, 'Review: 2 reviewers, standing') === '',
  'deadlock exit: "Review: 2 reviewers" names no trigger, so the clear stands');
check(/CHANGES from skyler/.test(namedBlocker([c(OWNER, 'VERDICT: CHANGES (reviewer: Skyler) on abc1234', 6), c(OWNER, CL, 8)], NEW, 'Review: fresh; triggers 1 and 5')),
  'deadlock exit: "triggers 1 and 5" on the Review: line still refuses the clear');
check(/CHANGES from skyler/.test(namedBlocker([c(OWNER, 'VERDICT: CHANGES (reviewer: Skyler) on abc1234', 6), c(OWNER, CL, 8)], NEW, 'Before: x\n\n- **Review:** external \u2014 2')),
  'deadlock exit: ROADMAP form "Review: external \u2014 2" (no word "trigger") still refuses the clear (#705 fresh review)');
check(/CHANGES from skyler/.test(namedBlocker([c(OWNER, 'VERDICT: CHANGES (reviewer: Skyler) on abc1234', 6), c(OWNER, CL, 8)], NEW, 'Review: blind \u2014 4b')),
  'deadlock exit: ROADMAP form "Review: blind \u2014 4b" still refuses the clear (#705 fresh review)');
check(/CHANGES from skyler/.test(namedBlocker([c(OWNER, 'VERDICT: CHANGES (reviewer: Skyler) on abc1234', 6), c(OWNER, CL, 8)], NEW, 'Review: 2 reviewers \u2014 5')),
  'deadlock exit: a reviewer count is dropped but a trigger after it still refuses the clear');

check(/waits on fresh review/.test(namedBlocker([REVIEW], SHA, 'Before: x\n\n- **Review:** external (trigger 1)')),
  '#695: a Review: line naming external review waits on a FRESH REVIEW OK on the head, with no hold label');
check(/waits on fresh review/.test(namedBlocker([REVIEW, c(OWNER, 'FRESH REVIEW OK 9999999', 7)], SHA, 'Review: blind')), '#695: a blind review needs the OK on the head, not an older one');
check(namedBlocker([REVIEW, c(OWNER, 'FRESH REVIEW #695 abc1234\nFRESH REVIEW OK abc1234', 7)], SHA, 'Review: fresh') === '', '#695: a FRESH REVIEW OK on the head meets a Review: fresh line');
check(namedBlocker([REVIEW], SHA, 'Review: standing (Howard)') === '', 'a Review: standing line needs no fresh OK');
const FCL = (t) => c(OWNER, `REVIEW CLEAR (reviewer: fresh review; trigger: ${t}): fresh reviewer ended, no successor`, 8);
check(/waits on fresh review/.test(namedBlocker([REVIEW, FCL('1')], SHA, 'Review: external \u2014 1')),
  '#705: no REVIEW CLEAR stands in for fresh review when the Review: line names external review');
check(/waits on fresh review/.test(namedBlocker([REVIEW, FCL('none')], SHA, '- **Review:** blind \u2014 3')),
  '#705: no REVIEW CLEAR stands in for fresh review when the Review: line names blind review');
check(/CHANGES from fresh review/.test(namedBlocker([REVIEW, c(OWNER, 'FRESH REVIEW #9 abc1234\nFRESH REVIEW CHANGES', 6), FCL('1')], SHA, 'Review: external \u2014 1')),
  '#705: a fresh CHANGES on an external PR is not cleared by a REVIEW CLEAR');
check(namedBlocker([REVIEW, FCL('1')], SHA, 'Reviewers: fresh review\nReview: fresh \u2014 1') === '',
  '#705: the deadlock exit still clears fresh review when the Review: line names neither external nor blind');
check(namedBlocker([REVIEW, c(OWNER, 'VERDICT: CHANGES (reviewer: Skyler) on abc1234', 6), c(OWNER, CL, 8), c(OWNER, 'FRESH REVIEW OK abc1234', 9)], SHA, 'Review: external \u2014 1') === '',
  '#705: on an external PR a clear for another reviewer still stands');

// restart.yml's BUSY-CHECK block: only a Pipeline run for this PR holds back the lost-review start.
const ryml = readFileSync(join(ROOT, '.github', 'workflows', 'restart.yml'), 'utf8');
const bc = ryml.match(/\/\/ BUSY-CHECK START[^\n]*\n([\s\S]*?)\n\s*\/\/ BUSY-CHECK END/);
check(!!bc, 'restart.yml has the BUSY-CHECK block');
const busyFor = new Function(bc[1] + '\nreturn busyFor;')();
const JOBS = { 1: [{ name: 'decide' }, { name: 'run #686 (claude-opus-5-5)' }], 2: [{ name: 'decide' }], 3: [{ name: 'decide' }, { name: 'run #68 (claude-opus-5-5)' }] };
const jobsOf = async (id) => JOBS[id] || [];
const R = (id, title, status = 'in_progress') => ({ id, display_title: title, status });
check(!(await busyFor(655, [R(1, 'Pipeline')], jobsOf)), "busy: an event run for another PR (#686) doesn't hold back #655");
check(await busyFor(686, [R(1, 'Pipeline')], jobsOf), 'busy: an event run for this PR does');
check(await busyFor(655, [R(2, 'Pipeline')], jobsOf), 'busy: an event run still deciding (no run job yet) counts as busy');
check(!(await busyFor(6, [R(3, 'Pipeline')], jobsOf)) && !(await busyFor(686, [R(3, 'Pipeline')], jobsOf)), 'busy: "#68 " is not #6 or #686');
check(await busyFor(655, [R(9, 'Pipeline review #655')], jobsOf) && !(await busyFor(655, [R(9, 'Pipeline merge #659')], jobsOf)), 'busy: a dispatched run counts only for its own PR');
check(!(await busyFor(655, [R(1, 'Pipeline', 'completed'), R(9, 'Pipeline review #655', 'completed')], jobsOf)), 'busy: finished runs never count');
// YAML reads " #" in a plain (unquoted) scalar as the start of a comment, so the job name must be quoted or it is just "run"
// (pipeline review of f0ae01a). Read the value the way YAML does: quoted, or cut at the first " #".
const yamlValue = (v) => (/^"(.*)"\s*(?:#.*)?$/.exec(v) || [])[1] ?? v.replace(/\s#.*$/, '').trim();
const runName = (/^ {4}name: (.*)$/m.exec(readFileSync(join(ROOT, '.github', 'workflows', 'pipeline.yml'), 'utf8').split('\n  run:\n')[1] || '') || [])[1] || '';
check(yamlValue(runName) === 'run #${{ needs.decide.outputs.pr }} (${{ needs.decide.outputs.model }})', "pipeline.yml's run job name, as YAML reads it, carries the PR number");
check(yamlValue('run #${{ x }} (y)') === 'run', 'yamlValue: an unquoted " #" ends the value, as in YAML');
for (const f of readdirSync(join(ROOT, '.github', 'workflows')).filter((x) => x.endsWith('.yml'))) {
  const bad = readFileSync(join(ROOT, '.github', 'workflows', f), 'utf8').split('\n').filter((l) => /^\s*(?:-\s+)?name: [^"'|>].*\s#/.test(l));
  check(bad.length === 0, `${f}: no unquoted name: value is cut short by " #" (${bad.join(' | ')})`);
}

// HOLD-CHECK (#709): auto-merge adds hold to a PR that needs named or external review, and lifts it only when every named
// reviewer (and a fresh reviewer for an external or blind Review: line) approves the head and ci-ok is green.
const hb = yml.match(/\/\/ HOLD-CHECK START[^\n]*\n([\s\S]*?)\n\s*\/\/ HOLD-CHECK END/);
check(!!hb, 'auto-merge.yml has the HOLD-CHECK block');
const H = new Function('V', hb[1] + '\nreturn { AUTOHOLD, holdToAdd, holdStays, holdLine };')(V);
const ev = (event, login, min) => ({ event, label: { name: 'hold' }, actor: { login }, created_at: at(min) });
const RB = 'Before: x\n\nReviewers: Francesca, Gale';
const HELD = ['hold'];
const nbH = (comments, body, sha = SHA) => namedBlocker(comments, sha, body, [], HELD, []);
const OKF = c(OWNER, 'VERDICT: OK (reviewer: Francesca) on abc1234', 6), OKG = c(OWNER, 'VERDICT: APPROVE (reviewer: Gale) on abc1234', 7);
const walter = [ev('labeled', OWNER, 1)];
const AUTO = [ev('labeled', 'github-actions[bot]', 1)], MARK = c('github-actions[bot]', `${H.AUTOHOLD}\nAuto-merge added hold`, 1);
const EB = 'Before: x\n\nReview: external — 1 (gate change; trigger-1 outside review)';
const EBR = EB + '\nReviewers: Francesca, Gale';
const FOK = c(OWNER, 'FRESH REVIEW OK abc1234: no blocking findings', 8);
// A person's hold always stays with people (Fresh governance review on #737: Watchdog, planner and interim holds).
check(/a person added it/.test(H.holdStays(RB, HELD, walter, [OKF, OKG], true, nbH([OKF, OKG], RB))), "stays: Walter's hold on a Reviewers: PR with every approval in place (#737)");
check(/a person added it/.test(H.holdStays(EBR, HELD, walter, [MARK, OKF, OKG, FOK], true, nbH([MARK, OKF, OKG, FOK], EBR))), "stays: a person's hold, even with every review and the auto-hold marker present");
check(/a person added it/.test(H.holdStays('Before: x', HELD, walter, [OKF, OKG], true, nbH([OKF, OKG], 'Before: x'))), 'stays: a hold on a PR with no review lines (freeze, planner, interim, Watchdog)');
check(/a person added it/.test(H.holdStays(EB, HELD, [...AUTO, ev('unlabeled', 'github-actions[bot]', 3), ev('labeled', OWNER, 5)], [MARK, FOK], true, nbH([MARK, FOK], EB))),
  "stays: a person added hold again after auto-merge's own hold came off");
check(/a person added it/.test(H.holdStays(EB, HELD, AUTO, [FOK], true, nbH([FOK], EB))), 'stays: a bot-added hold without the auto-hold marker is not taken as its own');
check(/a person added it/.test(H.holdStays(EB, HELD, [...AUTO, ev('unlabeled', 'github-actions[bot]', 3), ev('labeled', 'github-actions[bot]', 5)], [MARK, FOK], true, nbH([MARK, FOK], EB))),
  "stays: a later bot hold with only an older marker is not taken as auto-merge's own (#737 review)");
// Its own hold: lifted only on a FRESH REVIEW OK of the head, every named approval, no open CHANGES and a green ci-ok.
check(H.holdStays(EB, HELD, AUTO, [MARK, FOK], true, nbH([MARK, FOK], EB)) === '', 'lift: its own external-review hold, once FRESH REVIEW OK names the head');
check(H.holdStays(EBR, HELD, AUTO, [MARK, FOK, OKF, OKG], true, nbH([MARK, FOK, OKF, OKG], EBR)) === '', 'lift: its own hold with a Reviewers: line once every named reviewer and the fresh reviewer approve the head');
check(/waits on fresh review/.test(H.holdStays(EB, HELD, AUTO, [MARK], true, nbH([MARK], EB))), 'stays: its own hold without a FRESH REVIEW OK');
check(/waits on fresh review/.test(H.holdStays(EB, HELD, AUTO, [MARK, c(OWNER, 'FRESH REVIEW OK 9999999', 8)], true, nbH([MARK, c(OWNER, 'FRESH REVIEW OK 9999999', 8)], EB))), 'stays: a FRESH REVIEW OK of an older head');
check(/waits on gale/.test(H.holdStays(EBR, HELD, AUTO, [MARK, FOK, OKF], true, nbH([MARK, FOK, OKF], EBR))), 'stays: one named reviewer has not approved');
const OLDG = c(OWNER, 'VERDICT: APPROVE (reviewer: Gale) on 9999999', 7);
check(/waits on gale/.test(H.holdStays(EBR, HELD, AUTO, [MARK, FOK, OKF, OLDG], true, nbH([MARK, FOK, OKF, OLDG], EBR))), 'stays: a reviewer approved an older head only');
const CHG = c(OWNER, 'VERDICT: CHANGES (reviewer: Gale) on abc1234', 9);
check(/CHANGES from gale/.test(H.holdStays(EBR, HELD, AUTO, [MARK, FOK, OKF, OKG, CHG], true, nbH([MARK, FOK, OKF, OKG, CHG], EBR))), 'stays: a named CHANGES not yet cleared');
check(/ci-ok not green/.test(H.holdStays(EB, HELD, AUTO, [MARK, FOK], false, nbH([MARK, FOK], EB))), 'stays: ci-ok red');
const CLG = c(OWNER, 'REVIEW CLEAR (reviewer: Gale; trigger: none): Gale ended, no successor named', 10);
check(/CHANGES from gale/.test(H.holdStays(EBR, HELD, AUTO, [MARK, FOK, OKF, OKG, CHG, CLG], true, nbH([MARK, FOK, OKF, OKG, CHG, CLG], EBR))), 'stays: no REVIEW CLEAR counts while hold is on');
const RP = 'Before: x\n\nReviewers: Francesca (records and plan text)';
check(nbH([OKF], RP) === '', 'a Reviewers: name with a parenthetical matches the tagged verdict (#707)');
check(/waits on francesca/.test(nbH([], RP)), 'a parenthetical name still waits for that reviewer');
check(H.holdStays(EB, [], AUTO, [MARK, FOK], true, '') === 'no hold', 'no hold label: nothing to lift');
// Adding: only an external or blind Review: line with a review missing on the head.
check(/waits on fresh review/.test(nbH([], EB)), 'an external Review: line waits on fresh review');
check(/Review: line names external/.test(H.holdToAdd(EB, [], [], nbH([], EB))), 'add: an external Review: line gets hold');
check(/Review: line names blind/.test(H.holdToAdd('Review: blind', [], [], nbH([], 'Review: blind'))), 'add: a blind Review: line gets hold');
check(H.holdToAdd(RB, [], [], nbH([OKF], RB)) === '', 'add: a Reviewers: line alone gets no hold (the named check blocks the merge; #737)');
check(H.holdToAdd(EB, [], [], nbH([FOK], EB)) === '', 'add: none when the reviews already approve the head');
check(H.holdToAdd(EB, [], [ev('labeled', OWNER, 1), ev('unlabeled', OWNER, 2)], nbH([], EB)) === '', 'add: never again once anyone removed hold');
check(H.holdToAdd(EB, HELD, [], nbH([], EB)) === '', 'add: not when hold is already on');
check(H.holdToAdd('Before: x\n\nReview: fresh', [], [], nbH([], 'Review: fresh')) === '', 'add: a plain fresh Review: line gets no hold (its FRESH REVIEW OK still gates the merge)');
check(H.holdToAdd('Before: x', [], [], '') === '', 'add: a PR with no review rule gets no hold');
const hl0 = yml.slice(yml.indexOf('for (const pr of prs)'));
// A person's HOLD line (MRG-09, #744): a closed-list condition lifts that person's hold once met on the head; free text never.
const HL = (cond, min = 2, login = OWNER) => c(login, `Holding for the outside review.\n\nHOLD: ${cond} (owner: Walter)`, min);
check(JSON.stringify(V.holds('HOLD: until FRESH REVIEW OK on head (owner: Walter)')) === JSON.stringify([{ cond: 'until FRESH REVIEW OK on head', owner: 'Walter', reviewer: 'fresh review' }]), 'holds: "until FRESH REVIEW OK on head" waits on fresh review');
check(V.holds('HOLD: DESIGN OK (owner: Jane)')[0].reviewer === 'design lead' && V.holds('HOLD: Game Data Check VERIFIED on head (owner: Gretchen)')[0].reviewer === 'game data check'
  && V.holds('HOLD: until VERDICT: APPROVE (reviewer: Howard) on head (owner: Gus)')[0].reviewer === 'howard', 'holds: DESIGN OK, VERIFIED and a tagged APPROVE map to their gate names');
check(V.holds('HOLD: VERDICT: OK (reviewer: Francesca) (owner: Walter)')[0].reviewer === 'francesca' && V.holds('HOLD: VERDICT: CHANGES (reviewer: Francesca) (owner: Walter)')[0].reviewer === null,
  'holds: VERDICT: OK names its reviewer like APPROVE (MRG-12 treats OK as approval); CHANGES is free text');
check(V.holds('HOLD: until Isaac says go (owner: Walter)')[0].reviewer === null && V.holds('HOLD: FRESH REVIEW OK and DESIGN OK (owner: Walter)')[0].reviewer === null, 'holds: free text, or two conditions, names no reviewer (the owner lifts it)');
check(V.holds('> HOLD: FRESH REVIEW OK (owner: Walter)').length === 0 && V.holds('Note: HOLD: FRESH REVIEW OK (owner: Walter)').length === 0, 'holds: a quoted line or one not starting HOLD: is not a hold line');
const WH = [ev('labeled', OWNER, 1)];
check(H.holdLine([HL('FRESH REVIEW OK')], WH, OWNER).reviewer === 'fresh review', 'holdLine: the owner-account HOLD line after the label counts');
check(H.holdLine([HL('FRESH REVIEW OK', 0)], WH, OWNER) === null, 'holdLine: a HOLD line posted before the last labeled event is not this hold\'s');
check(H.holdLine([HL('FRESH REVIEW OK', 2, 'claude[bot]')], WH, OWNER) === null, 'holdLine: a claude[bot] comment is never a HOLD line');
check(H.holdLine([HL('FRESH REVIEW OK', 2), HL('until Isaac says go', 3)], WH, OWNER).reviewer === null, 'holdLine: the last HOLD line counts');
const PB = 'Before: x';
const nbP = (comments, need) => namedBlocker(comments, SHA, PB, need, HELD, []);
const lineF = H.holdLine([HL('FRESH REVIEW OK')], WH, OWNER);
check(H.holdStays(PB, HELD, WH, [HL('FRESH REVIEW OK'), FOK], true, (x) => nbP([HL('FRESH REVIEW OK'), FOK], x), lineF) === '', "lift: a person's hold whose HOLD condition (FRESH REVIEW OK) is met on the head");
check(/waits on fresh review/.test(H.holdStays(PB, HELD, WH, [HL('FRESH REVIEW OK')], true, (x) => nbP([HL('FRESH REVIEW OK')], x), lineF)), "stays: a person's hold whose condition is not met yet");
check(/waits on fresh review/.test(H.holdStays(PB, HELD, WH, [HL('FRESH REVIEW OK'), c(OWNER, 'FRESH REVIEW OK 9999999', 8)], true, (x) => nbP([HL('FRESH REVIEW OK'), c(OWNER, 'FRESH REVIEW OK 9999999', 8)], x), lineF)), "stays: the condition met only on an older head");
check(/ci-ok not green/.test(H.holdStays(PB, HELD, WH, [HL('FRESH REVIEW OK'), FOK], false, (x) => nbP([HL('FRESH REVIEW OK'), FOK], x), lineF)), "stays: a person's hold with its condition met but ci-ok red");
const lineT = H.holdLine([HL('until Isaac says go')], WH, OWNER);
check(/not one auto-merge can check/.test(H.holdStays(PB, HELD, WH, [HL('until Isaac says go'), FOK], true, nbP([HL('until Isaac says go'), FOK], []), lineT)), "stays: a person's hold with a free-text condition, whatever reviews are in");
check(/waits on fresh review/.test(H.holdStays(PB, HELD, WH, [HL('FRESH REVIEW OK')], true, (x) => nbP([HL('FRESH REVIEW OK')], x), lineF)) && H.holdStays(PB, HELD, WH, [HL('FRESH REVIEW OK')], true, (x) => nbP([HL('FRESH REVIEW OK')], []), lineF) === '',
  'stays: the HOLD reviewer is added by holdStays itself (a blocker that ignores it would lift; the real one does not)');
check(/cannot check/.test(H.holdStays(PB, HELD, WH, [HL('FRESH REVIEW OK'), FOK], true, '', lineF)), "stays: a person's HOLD condition with only a precomputed blocker is never lifted");
check(/posted no HOLD line/.test(H.holdStays(PB, HELD, WH, [FOK], true, nbP([FOK], []), null)), "stays: a person's hold with no HOLD line");
const lineH = H.holdLine([HL('VERDICT: APPROVE (reviewer: Howard)')], WH, OWNER);
const OKH = c(OWNER, 'VERDICT: APPROVE (reviewer: Howard) on abc1234', 6), CHH = c(OWNER, 'VERDICT: CHANGES (reviewer: Howard) on abc1234', 7);
check(H.holdStays(PB, HELD, WH, [HL('VERDICT: APPROVE (reviewer: Howard)'), OKH], true, (x) => nbP([OKH], x), lineH) === '', 'lift: a tagged APPROVE condition met on the head');
check(/CHANGES from howard/.test(H.holdStays(PB, HELD, WH, [OKH, CHH], true, (x) => nbP([OKH, CHH], x), lineH)), 'stays: the named reviewer approved, then asked for changes');
check(/waits on francesca, gale/.test(H.holdStays(RB, HELD, WH, [FOK], true, (x) => namedBlocker([FOK], SHA, RB, x, HELD, []), lineF)), "stays: the condition is met but the body's Reviewers: names still wait (every gate still counts)");
// Reviewers: line edge cases (#745 review): a name only in parentheses, and an unclosed "(".
check(V.reviewers('Reviewers: (Gale, Howard)') + '' === 'gale,howard', 'verdicts: a parenthesis around the whole list keeps every name (#750 review)');
check(V.holds('HOLD: FRESH REVIEW OK on abc1234 (owner: Walter)')[0].reviewer === 'fresh review' && V.holds('HOLD: until DESIGN OK on f00dfee0 (owner: Jane)')[0].reviewer === 'design lead',
  'holds: "… on <sha7>" names its reviewer like "on head" (the review must still name the head; #750 review)');
check(V.reviewers('Reviewers: (Gale)') + '' === 'gale' && V.reviewers('Reviewers: Howard (code, Gale') + '' === 'howard,gale', 'verdicts: "(Gale)" keeps Gale; an unclosed "(" keeps both names (#745 review)');
check(!/Reviewers: line\) to approve/.test(yml), 'the wait message no longer says "(Reviewers: line)" for a Review: line or implied wait (#745 review)');
check(/holdStays\([^\n]*blockerFor, line\)/.test(hl0), 'loop: holdStays gets the blocker function and the HOLD line');
// The loop: lift before the gates, then ask for the pipeline review; the freeze and every other gate still run after a lift.
const hl = yml.slice(yml.indexOf('for (const pr of prs)'));
const liftAt = hl.indexOf("name: 'hold' });"), mergeAt = hl.indexOf('github.rest.pulls.merge(');
check(liftAt > 0 && liftAt < hl.indexOf('const named = namedBlocker(comments, sha') && liftAt < hl.indexOf('const frozen = freezeBlocker(') && hl.indexOf('const frozen = freezeBlocker(') < mergeAt,
  'loop: hold is lifted before the named, design, data and freeze checks, which still run before the merge');
check(/if \(stays\) \{[^\n]*?continue; \}\s*\n\s*await github\.rest\.issues\.removeLabel/.test(hl), 'loop: hold is removed only when holdStays is empty');
check(/if \(add\) \{[\s\S]{0,600}?continue;\s*\n\s*\}/.test(hl), 'loop: a PR that just got hold is not merged in the same pass');
check(/lifted && !\(last && last\.body\.includes\(sha\.slice\(0, 7\)\)\)\) \{[\s\S]{0,400}?workflow_id: 'pipeline\.yml'[\s\S]{0,200}?step: 'review'[\s\S]{0,200}?continue;/.test(hl),
  'loop: after a lift with no review of the head, the pipeline review is requested and the PR waits for its APPROVE');
check(/namedBlocker\(comments, sha, pr\.body \|\| '', \[\.\.\.imp, \.\.\.extra\], \[\.\.\.new Set\(\[\.\.\.labels, 'hold'\]\)\], all\)/.test(hl), 'loop: the lift decision counts hold, so no REVIEW CLEAR stands in');
check(!/\.filter\(\(p\) => [^\n]*\n[^\n]*l\.name === 'hold'/.test(yml.slice(yml.indexOf('const prs ='), yml.indexOf('// DESIGN-CHECK START'))), 'PR list: held PRs are read so their hold can be lifted');

// Reviewers: names off the roster (#741, Walter): "Legal sign-off per Chuck's ruling" waited 84 min with no word.
const HEADS = readdirSync(join(ROOT, 'docs', 'team')).filter((f) => f.endsWith('.md')).map((f) => readFileSync(join(ROOT, 'docs', 'team', f), 'utf8').split('\n')[0]);
const RO = V.roster(HEADS);
check(['chuck', 'gus', 'lydia', 'francesca', 'howard', 'gale', 'walter', 'jane', 'gretchen', 'design lead', 'game data check', 'fresh review'].every((x) => RO.has(x))
  && !RO.has('engineering') && !RO.has('support'), 'roster: every person file "# Name (Role)", the aliases and gate names; topic files are not names');
const B741 = "Reviewers: gretchen (DATA OK on the Build sources text); Legal sign-off per Chuck's ruling";
check(V.unknownReviewers(B741, RO) + '' === "legal sign-off per chuck's ruling" && V.unknownReviewers('Reviewers: gretchen; chuck', RO).length === 0
  && V.unknownReviewers('Reviewers: Francesca (records), Game Data Check', RO).length === 0 && V.unknownReviewers('No line', RO).length === 0, "roster: #741's line names one unknown reviewer; first names, notes and gate names pass");
const rm = yml.match(/\/\/ ROSTER-CHECK START\n([\s\S]*?)\n\s*\/\/ ROSTER-CHECK END/);
check(!!rm, 'auto-merge.yml has the ROSTER-CHECK block');
const rosterNote = rm ? new Function('V', 'ROSTER', rm[1] + '\nreturn rosterNote;')(V, RO) : () => '';
const note = rosterNote(B741, []);
check(note.startsWith('<!-- auto-merge:unknown-reviewer -->') && note.includes(`"legal sign-off per chuck's ruling"`) && rosterNote('Reviewers: gretchen; chuck', []) === '', 'roster note: names the unknown entry; none for a clean line');
check(rosterNote(B741, [c('github-actions[bot]', note, 3)]) === '' && rosterNote(B741, [c('HackTheMeatball', note, 3)]) !== ''
  && rosterNote('Reviewers: chuck, bob', [c('github-actions[bot]', note, 3)]).includes('"bob"'), 'roster note: posted once per list by the bot; a changed list gets a new note');
check(/sparse-checkout: \|\n\s+tools\/verdicts\.cjs\n\s+docs\/team\n/.test(yml), 'roster: auto-merge checks out docs/team from main');
check(hl.indexOf('rosterNote(pr.body') > 0 && hl.indexOf('rosterNote(pr.body') < hl.indexOf('// HOLD: add or lift it') && !/rosterNote[^\n]*continue/.test(hl),
  'loop: the roster note comes before the hold check and never skips the gates (the unknown name still blocks)');

console.log(`\n${n - fail}/${n} auto-merge checks passed`);
console.log(fail ? 'AUTOMERGE CHECKS FAILED' : 'AUTOMERGE CHECKS PASSED');
process.exit(fail ? 1 : 0);
